from httpbin.core import app
client = app.test_client()

def test_weighted_comma_list_respects_weights():
    allowed = {200, 500}
    counts = {200: 0, 500: 0}
    for _ in range(300):
        r = client.get('/status/200:9,500:1', follow_redirects=False)
        assert r.status_code in allowed, f'Unexpected {r.status_code}'
        counts[r.status_code] += 1
    assert counts[200] > counts[500], (
        f'Expected 200 more frequent than 500, got {counts}'
    )
    assert counts[200] + counts[500] == 300

from httpbin.core import app
client = app.test_client()

def test_comma_list_does_not_return_unlisted_code():
    allowed = {201, 202}
    for _ in range(50):
        r = client.get('/status/201,202', follow_redirects=False)
        assert r.status_code in allowed, f'Got {r.status_code}, expected 201 or 202'
        assert r.status_code != 200
        assert r.status_code != 203
        assert r.status_code != 400
